-- Mission 1000 v2: reviewed onboarding copy, preserving IDs, schedules and active flags.
-- Run manually after taking a database backup and reviewing the active-template export.
-- Stop follow-up cron while applying. Do not run v1 after this migration.
-- Backups preserve the first pre-v2 snapshot per sequence ID, including reruns.
CREATE TABLE IF NOT EXISTS mission1000_v2_sequence_backup LIKE followup_sequences;
-- Reviewed against the uploaded Hostinger snapshot, 13 October 2026.
-- Copy hashes contain no email addresses, names, credentials or original template text.
-- Preflight is all-or-none: if any of the 20 standard rows changed since review,
-- no backup rows or copy changes are made. Read the preflight result before proceeding.
CREATE TEMPORARY TABLE mission1000_v2_expected (
 id INT PRIMARY KEY, target VARCHAR(10), day_offset INT,
 before_hash CHAR(64), after_hash CHAR(64)
);
