START TRANSACTION;
SELECT id FROM followup_sequences WHERE id IN (SELECT id FROM mission1000_v2_expected) FOR UPDATE;
SET @mission1000_snapshot_ok = (
 SELECT COUNT(*) = 20 FROM followup_sequences f JOIN mission1000_v2_expected e
 ON f.id=e.id AND f.target=e.target AND f.day_offset=e.day_offset
 WHERE SHA2(CONCAT_WS(CHAR(31), f.subject, f.subject_b, f.body), 256) IN (e.before_hash,e.after_hash)
);
SELECT @mission1000_snapshot_ok AS all_20_reviewed_templates_match;

INSERT IGNORE INTO mission1000_v2_sequence_backup SELECT * FROM followup_sequences WHERE @mission1000_snapshot_ok = 1;

UPDATE followup_sequences SET subject='Your Simple2Success access and next step', subject_b='Start with a clear overview', body='<html><body style="font-family:Arial,sans-serif;line-height:1.6;max-width:600px;margin:24px auto;padding:16px;"><p>Hi {{name}},</p><p>Your free system account is ready. Explore how the partner registration works, then return and save your Partner ID in Step 2. That completes your setup. Our mission is to support 1,000 people and families in building additional income; results are not guaranteed.</p><p><a href="{{cta_url}}">View my start page</a></p><p>Your Simple2Success Eagle Team</p></body></html>' WHERE @mission1000_snapshot_ok = 1 AND id IN (SELECT id FROM mission1000_v2_expected) AND target='lead' AND day_offset=1;

UPDATE followup_sequences SET subject='What happens when you register?', subject_b='Understand the registration before you start', body='<html><body style="font-family:Arial,sans-serif;line-height:1.6;max-width:600px;margin:24px auto;padding:16px;"><p>Hi {{name}},</p><p>Your start page links to partner registration. Your Simple2Success account is free; partner-registration fees and product packages are separate. Review the local fees, package contents and recurring charges before confirming. After registration, save your Partner ID in Step 2. If you already have an ID, you can go straight to that field.</p><p><a href="{{cta_url}}">Review the registration steps</a></p><p>Your Simple2Success Eagle Team</p></body></html>' WHERE @mission1000_snapshot_ok = 1 AND id IN (SELECT id FROM mission1000_v2_expected) AND target='lead' AND day_offset=2;

UPDATE followup_sequences SET subject='Already registered? Here is the next step', subject_b='Where to save your Partner ID', body='<html><body style="font-family:Arial,sans-serif;line-height:1.6;max-width:600px;margin:24px auto;padding:16px;"><p>Hi {{name}},</p><p>If you have completed partner registration, find your Partner ID in the confirmation email or partner account. Save that number in Step 2 to finish setup. Never enter your partner password. If registration is still open, the same page will guide you.</p><p><a href="{{cta_url}}">Continue my setup</a></p><p>Your Simple2Success Eagle Team</p></body></html>' WHERE @mission1000_snapshot_ok = 1 AND id IN (SELECT id FROM mission1000_v2_expected) AND target='lead' AND day_offset=3;

UPDATE followup_sequences SET subject='What would you like to clarify?', subject_b='Questions before your next step?', body='<html><body style="font-family:Arial,sans-serif;line-height:1.6;max-width:600px;margin:24px auto;padding:16px;"><p>Hi {{name}},</p><p>It is reasonable to ask about time, costs or how the business works before deciding. Read the overview and use the support link on your start page for anything that remains unclear. You choose when to continue.</p><p><a href="{{cta_url}}">View instructions and support</a></p><p>Your Simple2Success Eagle Team</p></body></html>' WHERE @mission1000_snapshot_ok = 1 AND id IN (SELECT id FROM mission1000_v2_expected) AND target='lead' AND day_offset=4;

UPDATE followup_sequences SET subject='One manageable step for today', subject_b='Continue when it fits your schedule', body='<html><body style="font-family:Arial,sans-serif;line-height:1.6;max-width:600px;margin:24px auto;padding:16px;"><p>Hi {{name}},</p><p>You do not need to finish everything today. Choose a time to review the registration, or save your Partner ID if you already have it. Your setup is complete when the ID is saved.</p><p><a href="{{cta_url}}">Open my next step</a></p><p>Your Simple2Success Eagle Team</p></body></html>' WHERE @mission1000_snapshot_ok = 1 AND id IN (SELECT id FROM mission1000_v2_expected) AND target='lead' AND day_offset=5;

UPDATE followup_sequences SET subject='Understand the company behind the system', subject_b='Review the business before deciding', body='<html><body style="font-family:Arial,sans-serif;line-height:1.6;max-width:600px;margin:24px auto;padding:16px;"><p>Hi {{name}},</p><p>The start page explains our product partner and links to further information. Review the products, compensation requirements and potential costs. A system can support your work, but customers and income are not automatic.</p><p><a href="{{cta_url}}">Explore the business overview</a></p><p>Your Simple2Success Eagle Team</p></body></html>' WHERE @mission1000_snapshot_ok = 1 AND id IN (SELECT id FROM mission1000_v2_expected) AND target='lead' AND day_offset=6;

UPDATE followup_sequences SET subject='Your first-week check-in', subject_b='Where would you like help?', body='<html><body style="font-family:Arial,sans-serif;line-height:1.6;max-width:600px;margin:24px auto;padding:16px;"><p>Hi {{name}},</p><p>Have you found the information you need? If you want to continue, your start page shows the registration and Partner ID steps. If you need help, use the support link there. It is also fine to take more time.</p><p><a href="{{cta_url}}">Review my next step</a></p><p>Your Simple2Success Eagle Team</p></body></html>' WHERE @mission1000_snapshot_ok = 1 AND id IN (SELECT id FROM mission1000_v2_expected) AND target='lead' AND day_offset=7;

UPDATE followup_sequences SET subject='A clear plan, at your own pace', subject_b='Your setup instructions are here', body='<html><body style="font-family:Arial,sans-serif;line-height:1.6;max-width:600px;margin:24px auto;padding:16px;"><p>Hi {{name}},</p><p>A useful plan makes the next action understandable. Your first goal here is to complete partner registration and save the resulting Partner ID. Later, you can review learning activities and costs before choosing how to proceed.</p><p><a href="{{cta_url}}">View my setup</a></p><p>Your Simple2Success Eagle Team</p></body></html>' WHERE @mission1000_snapshot_ok = 1 AND id IN (SELECT id FROM mission1000_v2_expected) AND target='lead' AND day_offset=10;

UPDATE followup_sequences SET subject='Need help finding your Partner ID?', subject_b='Your Partner ID completes setup', body='<html><body style="font-family:Arial,sans-serif;line-height:1.6;max-width:600px;margin:24px auto;padding:16px;"><p>Hi {{name}},</p><p>Already registered with our partner? You can usually find your Partner ID in your confirmation email or partner account. Save it in Step 2. If you cannot find it, use the support link on the start page.</p><p><a href="{{cta_url}}">Open Step 2</a></p><p>Your Simple2Success Eagle Team</p></body></html>' WHERE @mission1000_snapshot_ok = 1 AND id IN (SELECT id FROM mission1000_v2_expected) AND target='lead' AND day_offset=13;

UPDATE followup_sequences SET subject='What would a realistic starting plan look like?', subject_b='Start with time, skills and a budget', body='<html><body style="font-family:Arial,sans-serif;line-height:1.6;max-width:600px;margin:24px auto;padding:16px;"><p>Hi {{name}},</p><p>Consider how much time you can regularly set aside, what you want to learn and what budget is appropriate for you. Building income takes customer demand and work, and results vary. Review the process before deciding.</p><p><a href="{{cta_url}}">Review the process</a></p><p>Your Simple2Success Eagle Team</p></body></html>' WHERE @mission1000_snapshot_ok = 1 AND id IN (SELECT id FROM mission1000_v2_expected) AND target='lead' AND day_offset=16;

UPDATE followup_sequences SET subject='Questions about costs or time?', subject_b='Make an informed next decision', body='<html><body style="font-family:Arial,sans-serif;line-height:1.6;max-width:600px;margin:24px auto;padding:16px;"><p>Hi {{name}},</p><p>Before proceeding, make sure you understand the work involved and any later product or advertising costs. You can use the support link on your start page to clarify your questions.</p><p><a href="{{cta_url}}">View guidance and support</a></p><p>Your Simple2Success Eagle Team</p></body></html>' WHERE @mission1000_snapshot_ok = 1 AND id IN (SELECT id FROM mission1000_v2_expected) AND target='lead' AND day_offset=19;

UPDATE followup_sequences SET subject='Your guide is still available', subject_b='Continue when you are ready', body='<html><body style="font-family:Arial,sans-serif;line-height:1.6;max-width:600px;margin:24px auto;padding:16px;"><p>Hi {{name}},</p><p>You can return to your setup instructions when you are ready. If you already registered, save your Partner ID in Step 2; otherwise review the registration first. There is no need to rush a decision.</p><p><a href="{{cta_url}}">Return to my start page</a></p><p>Your Simple2Success Eagle Team</p></body></html>' WHERE @mission1000_snapshot_ok = 1 AND id IN (SELECT id FROM mission1000_v2_expected) AND target='lead' AND day_offset=23;

UPDATE followup_sequences SET subject='Would you like to continue?', subject_b='Your next step and support options', body='<html><body style="font-family:Arial,sans-serif;line-height:1.6;max-width:600px;margin:24px auto;padding:16px;"><p>Hi {{name}},</p><p>If the approach fits your goals, your setup instructions are available below. If it does not fit, you can unsubscribe from these marketing reminders using the link below. Your decision is yours.</p><p><a href="{{cta_url}}">Review my next step</a></p><p>Your Simple2Success Eagle Team</p></body></html>' WHERE @mission1000_snapshot_ok = 1 AND id IN (SELECT id FROM mission1000_v2_expected) AND target='lead' AND day_offset=27;

UPDATE followup_sequences SET subject='A final check-in from this onboarding series', subject_b='Your start page remains available', body='<html><body style="font-family:Arial,sans-serif;line-height:1.6;max-width:600px;margin:24px auto;padding:16px;"><p>Hi {{name}},</p><p>This is the final scheduled check-in in this onboarding series. You can return to your start page whenever you want to review the process. For questions, use the support link there. You can unsubscribe from marketing reminders below.</p><p><a href="{{cta_url}}">Open my start page</a></p><p>Your Simple2Success Eagle Team</p></body></html>' WHERE @mission1000_snapshot_ok = 1 AND id IN (SELECT id FROM mission1000_v2_expected) AND target='lead' AND day_offset=30;

UPDATE followup_sequences SET subject='Your PM Ref-ID is saved — continue with Step 3', subject_b='Partner ID saved. What comes next?', body='<html><body style="font-family:Arial,sans-serif;line-height:1.6;max-width:600px;margin:24px auto;padding:16px;"><p>Hi {{name}},</p><p>Your PM Ref-ID is saved, so Steps 1 and 2 are complete. Continue with Step 3: use the traffic guide to plan a measured first campaign with your personal link. Then follow Step 4 for your product start and Step 5 to repeat and review. Setup is a starting point, not an income result.</p><p><a href="{{cta_url}}">Review my next steps</a></p><p>Your Simple2Success Eagle Team</p></body></html>' WHERE @mission1000_snapshot_ok = 1 AND id IN (SELECT id FROM mission1000_v2_expected) AND target='member' AND day_offset=1;

UPDATE followup_sequences SET subject='Review your product options and costs', subject_b='An informed product decision', body='<html><body style="font-family:Arial,sans-serif;line-height:1.6;max-width:600px;margin:24px auto;padding:16px;"><p>Hi {{name}},</p><p>Review the available product options, recurring costs and compensation requirements in your country. If you already made a choice, check that it still fits your needs and budget. Ask for help with anything unclear.</p><p><a href="{{cta_url}}">Review the next-step guide</a></p><p>Your Simple2Success Eagle Team</p></body></html>' WHERE @mission1000_snapshot_ok = 1 AND id IN (SELECT id FROM mission1000_v2_expected) AND target='member' AND day_offset=3;

UPDATE followup_sequences SET subject='Your first customer-focused action', subject_b='Put learning into practice', body='<html><body style="font-family:Arial,sans-serif;line-height:1.6;max-width:600px;margin:24px auto;padding:16px;"><p>Hi {{name}},</p><p>Review where you are in the five-step plan. Check your Step-3 campaign, your Step-4 product start and whether you are ready to repeat the process in Step 5. Track real leads, saved PM Ref-IDs and costs. Ask the team for help with the next open step.</p><p><a href="{{cta_url}}">View my next steps</a></p><p>Your Simple2Success Eagle Team</p></body></html>' WHERE @mission1000_snapshot_ok = 1 AND id IN (SELECT id FROM mission1000_v2_expected) AND target='member' AND day_offset=7;

UPDATE followup_sequences SET subject='How are your activities and costs developing?', subject_b='A two-week review', body='<html><body style="font-family:Arial,sans-serif;line-height:1.6;max-width:600px;margin:24px auto;padding:16px;"><p>Hi {{name}},</p><p>Review your activity, customer conversations and any costs so far. If you use paid advertising, compare the spend with the outcomes before buying more. A saved Partner ID and more traffic alone do not guarantee income.</p><p><a href="{{cta_url}}">Review my plan</a></p><p>Your Simple2Success Eagle Team</p></body></html>' WHERE @mission1000_snapshot_ok = 1 AND id IN (SELECT id FROM mission1000_v2_expected) AND target='member' AND day_offset=14;

UPDATE followup_sequences SET subject='Keep what works, improve what does not', subject_b='Your progress check-in', body='<html><body style="font-family:Arial,sans-serif;line-height:1.6;max-width:600px;margin:24px auto;padding:16px;"><p>Hi {{name}},</p><p>Continue Step 5: repeat the five-step process and review real results. If a campaign brings leads but no saved PM Ref-IDs, ask the team to help identify the bottleneck before increasing spend. Keep the plan consistent and use the evidence to improve the relevant step.</p><p><a href="{{cta_url}}">Review my next action</a></p><p>Your Simple2Success Eagle Team</p></body></html>' WHERE @mission1000_snapshot_ok = 1 AND id IN (SELECT id FROM mission1000_v2_expected) AND target='member' AND day_offset=21;

UPDATE followup_sequences SET subject='Your monthly review: customers, income and costs', subject_b='Review your results and next decision', body='<html><body style="font-family:Arial,sans-serif;line-height:1.6;max-width:600px;margin:24px auto;padding:16px;"><p>Hi {{name}},</p><p>Review customer activity, commissions and expenses together. Our mission aims to support 1,000 people and families in building additional income. Your own progress should be judged by real outcomes and costs, not registrations alone.</p><p><a href="{{cta_url}}">Plan my next month</a></p><p>Your Simple2Success Eagle Team</p></body></html>' WHERE @mission1000_snapshot_ok = 1 AND id IN (SELECT id FROM mission1000_v2_expected) AND target='member' AND day_offset=30;

COMMIT;
DROP TEMPORARY TABLE mission1000_v2_expected;
-- Existing nonstandard offsets remain unchanged and require separate review.
